#include <iostream>
#include <cmath>

using namespace std;

/**
 * Problem: 10528 - Light, more light
 * 
 * 解題思路：
 * 1. 有 n 盞燈，進行 n 輪切換。第 i 輪切換編號為 i 的倍數的燈。
 * 2. 第 n 盞燈在第 i 輪被切換，若且唯若 i 是 n 的約數。
 * 3. 第 n 盞燈最後是否亮著，取決於 n 的約數個數是奇數還是偶數。
 * 4. 一個整數的約數個數為奇數，當且僅當該數是一個完全平方數。
 * 5. 因此問題轉化為：判斷 n 是否為完全平方數。
 * 6. 注意 n 的範圍可達 2^32 - 1，需使用 long long 或 unsigned int。
 */

int main() {
    long long n;
    while (cin >> n && n != 0) {
        long long root = round(sqrt(n));
        if (root * root == n) {
            cout << "yes" << endl;
        } else {
            cout << "no" << endl;
        }
    }
    return 0;
}
